/**
 * delete-archived-articles — remove from the DATABASE the articles listed in
 * shared/retiredArticles.ts (generated by archive-articles), but ONLY those whose markdown
 * file exists in the archive directory. Uses the app's own deleteArticle(), so comments,
 * likes, attachments rows and the cover/attachment files in storage go with them.
 *
 *   pnpm delete:archived                         → dry run (lists what would be deleted)
 *   pnpm delete:archived --apply                 → deletes
 *   pnpm delete:archived --archive <dir>         (default ~/Desktop/ruach-way-articles)
 *
 * Against production: run it where the production env is available, e.g.
 *   railway run -- pnpm delete:archived --apply
 */
import fs from "fs";
import path from "path";
import os from "os";
import { RETIRED_ARTICLE_SLUGS } from "../shared/retiredArticles";
import { getArticles, deleteArticle } from "../server/db";

async function main() {
  const apply = process.argv.includes("--apply");
  const i = process.argv.indexOf("--archive");
  const ARCHIVE = path.resolve(i > -1 ? process.argv[i + 1] : path.join(os.homedir(), "Desktop", "ruach-way-articles"));

  const all = await getArticles();
  const targets = all.filter((a) => RETIRED_ARTICLE_SLUGS.has(a.slug));
  const safe = targets.filter((a) => fs.existsSync(path.join(ARCHIVE, "articles", `${a.slug}.md`)));
  const unsafe = targets.filter((a) => !safe.includes(a));

  console.log(`${all.length} articles in DB · ${targets.length} retired · ${safe.length} verified in archive at ${ARCHIVE}`);
  for (const a of unsafe) console.log(`  SKIP (not in archive): ${a.slug} — ${a.title}`);
  for (const a of safe) console.log(`  ${apply ? "DELETE" : "would delete"}: ${a.slug} — ${a.title}`);
  if (!apply) { console.log("\nDry run. Add --apply to delete."); return; }

  let n = 0;
  for (const a of safe) { await deleteArticle(a.id); n++; process.stdout.write("."); }
  console.log(`\nDeleted ${n} articles.`);
}

main().then(() => process.exit(0)).catch((err) => { console.error(err); process.exit(1); });
